package stock

import (
	"fmt"
	"tarnbrook/internal/importer"
)

// Table holds the stock of all SKUs, indexed by name. One row per SKU.
type Table struct {
	SKUs map[string]importer.Row
}

// New creates an empty stock table.
func New() *Table {
	return &Table{SKUs: make(map[string]importer.Row)}
}

// Add adds or merges a row into the stock table. If the SKU already exists,
// quantities are summed; if the unit differs, an error is returned.
func (t *Table) Add(row importer.Row) error {
	existing, exists := t.SKUs[row.Name]
	if !exists {
		t.SKUs[row.Name] = row
		return nil
	}
	if existing.Unit != row.Unit {
		return fmt.Errorf("SKU %q: unit mismatch (have %q, want %q)", row.Name, existing.Unit, row.Unit)
	}
	existing.Quantity += row.Quantity
	t.SKUs[row.Name] = existing
	return nil
}

// All returns all rows in the table.
func (t *Table) All() []importer.Row {
	var rows []importer.Row
	for _, row := range t.SKUs {
		rows = append(rows, row)
	}
	return rows
}

package main

import (
	"fmt"
	"os"
	"tarnbrook/internal/importer"
	"tarnbrook/internal/stock"
)

// ImportStock reads a CSV file and imports all rows into a stock table.
// Malformed rows are reported but the import continues.
// For each SKU, if it appears multiple times in the CSV or already exists in the table,
// quantities are summed; if the unit differs, an error is returned.
// Returns the updated stock table or an error if a merge fails.
func ImportStock(filename string, table *stock.Table) ([]importer.RowError, error) {
	file, err := os.Open(filename)
	if err != nil {
		return nil, fmt.Errorf("opening %s: %w", filename, err)
	}
	defer file.Close()

	rows, bad, err := importer.ReadStock(file)
	if err != nil {
		return bad, fmt.Errorf("reading %s: %w", filename, err)
	}

	for _, row := range rows {
		if err := table.Add(row); err != nil {
			return bad, fmt.Errorf("merging %s: %w", filename, err)
		}
	}

	return bad, nil
}

package main

import (
	"os"
	"path/filepath"
	"testing"
	"tarnbrook/internal/importer"
	"tarnbrook/internal/stock"
)

func TestImportStock(t *testing.T) {
	t.Parallel()

	t.Run("repeated sku in csv merged with existing table entry", func(t *testing.T) {
		t.Parallel()

		// Create a temporary CSV file with a duplicate SKU and a new SKU
		csvContent := "Washer,200,pcs\nWasher,150,pcs\nBolt M6,100,boxes\n"
		csvFile := filepath.Join(t.TempDir(), "import.csv")
		if err := os.WriteFile(csvFile, []byte(csvContent), 0o644); err != nil {
			t.Fatal(err)
		}

		// Start with a stock table that already has Washer
		table := stock.New()
		table.Add(importer.Row{Name: "Washer", Quantity: 50, Unit: "pcs"})

		// Import the CSV
		bad, err := ImportStock(csvFile, table)
		if err != nil {
			t.Fatalf("ImportStock failed: %v", err)
		}
		if len(bad) != 0 {
			t.Fatalf("expected no malformed rows, got %v", bad)
		}

		// Verify the table has exactly one Washer row with summed quantity: 50 + 200 + 150 = 400
		if len(table.SKUs) != 2 {
			t.Fatalf("expected 2 SKUs, got %d", len(table.SKUs))
		}

		washer, exists := table.SKUs["Washer"]
		if !exists {
			t.Fatal("Washer not found in table")
		}
		if washer.Quantity != 400 || washer.Unit != "pcs" {
			t.Fatalf("Washer: want {Name: Washer, Quantity: 400, Unit: pcs}, got %+v", washer)
		}

		bolt, exists := table.SKUs["Bolt M6"]
		if !exists {
			t.Fatal("Bolt M6 not found in table")
		}
		if bolt.Quantity != 100 || bolt.Unit != "boxes" {
			t.Fatalf("Bolt M6: want {Name: Bolt M6, Quantity: 100, Unit: boxes}, got %+v", bolt)
		}
	})

	t.Run("unit mismatch rejected", func(t *testing.T) {
		t.Parallel()

		csvContent := "Washer,100,boxes\n"
		csvFile := filepath.Join(t.TempDir(), "import.csv")
		if err := os.WriteFile(csvFile, []byte(csvContent), 0o644); err != nil {
			t.Fatal(err)
		}

		table := stock.New()
		table.Add(importer.Row{Name: "Washer", Quantity: 50, Unit: "pcs"})

		bad, err := ImportStock(csvFile, table)
		if err == nil {
			t.Fatal("expected error for unit mismatch, got nil")
		}
		if len(bad) != 0 {
			t.Fatalf("expected no malformed rows, got %v", bad)
		}
	})
}

package main

import (
	"errors"
	"fmt"
)

// ErrNoPackSize is returned for a SKU that has no pack size configured.
var ErrNoPackSize = errors.New("sku has no pack size set")

// PackSizes says how many pieces are in a box and how many boxes are on a pallet, for one SKU.
type PackSizes struct {
	PiecesPerBox   int
	BoxesPerPallet int
}

var piecesPer = map[string]func(PackSizes) int{
	"pcs":     func(PackSizes) int { return 1 },
	"boxes":   func(p PackSizes) int { return p.PiecesPerBox },
	"pallets": func(p PackSizes) int { return p.PiecesPerBox * p.BoxesPerPallet },
}

// Convert converts qty of a SKU between pcs, boxes and pallets using its pack sizes.
func Convert(sku string, sizes map[string]PackSizes, qty int, from, to string) (int, error) {
	pack, ok := sizes[sku]
	if !ok || pack.PiecesPerBox == 0 || pack.BoxesPerPallet == 0 {
		return 0, fmt.Errorf("convert %s: %w", sku, ErrNoPackSize)
	}

	fromN, okFrom := piecesPer[from]
	toN, okTo := piecesPer[to]
	if !okFrom || !okTo {
		return 0, fmt.Errorf("convert %s: unknown unit %q or %q", sku, from, to)
	}

	pieces := qty * fromN(pack)
	per := toN(pack)
	if pieces%per != 0 {
		return 0, fmt.Errorf("convert %s: %d %s is not a whole number of %s", sku, qty, from, to)
	}

	return pieces / per, nil
}

package main

import (
	"errors"
	"testing"
)

func TestConvert(t *testing.T) {
	t.Parallel()

	sizes := map[string]PackSizes{"BOLT-M6": {PiecesPerBox: 50, BoxesPerPallet: 40}}

	cases := []struct {
		name     string
		qty      int
		from, to string
		want     int
	}{
		{"pcs to boxes", 150, "pcs", "boxes", 3},
		{"boxes to pallets", 80, "boxes", "pallets", 2},
		{"pallets to pcs", 1, "pallets", "pcs", 2000},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			got, err := Convert("BOLT-M6", sizes, tc.qty, tc.from, tc.to)
			if err != nil || got != tc.want {
				t.Fatalf("Convert = %d, %v; want %d", got, err, tc.want)
			}
		})
	}

	t.Run("missing pack size refused", func(t *testing.T) {
		t.Parallel()
		if _, err := Convert("NUT-M8", sizes, 1, "boxes", "pcs"); !errors.Is(err, ErrNoPackSize) {
			t.Fatalf("want ErrNoPackSize, got %v", err)
		}
	})

	t.Run("non whole result refused", func(t *testing.T) {
		t.Parallel()
		if _, err := Convert("BOLT-M6", sizes, 7, "pcs", "boxes"); err == nil {
			t.Fatal("want an error for 7 pcs in boxes of 50")
		}
	})
}

